(()=>{'use strict';
const C=WeddingCore,db=WStore,$=s=>document.querySelector(s),esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={calendar:'M8 2v4m8-4v4M3 9h18M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2Z M7 13h3m4 0h3m-10 4h3',music:'M9 18V5l11-2v13M9 8l11-2M9 18c0 2-6 3-6 0s6-3 6 0m11-2c0 2-6 3-6 0s6-3 6 0',brand:'M12 3l8 4v6c0 5-8 9-8 9s-8-4-8-9V7l8-4Zm-4 9 3 3 5-6',backup:'M4 16v5h16v-5M12 3v13m-5-5 5 5 5-5',plus:'M12 5v14M5 12h14',search:'M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16Zm6-2 6 6',dots:'M5 12h.01M12 12h.01M19 12h.01',check:'m5 12 4 4L19 6',clock:'M12 7v5l4 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',leaf:'M4 20c0-8 5-15 16-16 1 12-5 17-12 14M5 19 16 8',up:'m6 15 6-6 6 6',down:'m6 9 6 6 6-6',copy:'M8 8h13v13H8V8ZM16 4V1H1v15h3',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',close:'m6 6 12 12M6 18 18 6',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',grip:'M8 5h.01M16 5h.01M8 12h.01M16 12h.01M8 19h.01M16 19h.01',file:'M14 2H4v20h16V8l-6-6Zm0 0v6h6M8 13h8m-8 4h6',headphones:'M3 14v-3a9 9 0 0 1 18 0v3M3 13h4v8H3v-8Zm14 0h4v8h-4v-8',play:'m8 4 12 8-12 8V4',restore:'M3 10a9 9 0 1 1 2 8M3 3v7h7',settings:'M4 7h16M4 17h16M8 4v6m8 4v6'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.file}"></path></svg>`;
const musicDrop=()=>`<div class="music-drop" data-drop-music role="button" tabindex="0" data-action="import-music" aria-label="拖拽音乐到此处或点击导入">${icon('music')}<b>拖拽音乐到这里</b><span>也可点击选择文件 · 支持多首 · 单首20MB以内</span></div>`;
const btn=(action,label,kind='',extra='')=>`<button type="button" class="btn ${kind}" data-action="${action}" ${extra}>${label}</button>`;
const ib=(action,title,name,extra='')=>`<button type="button" class="icon-btn" title="${title}" aria-label="${title}" data-action="${action}" ${extra}>${icon(name)}</button>`;
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
let state,base=0,sequence=0,saved=0,timer,running,modalSubmit,dragIndex=-1,conflicted=false;let brandUrl='',logoInfo=null;const urls=new Map();const ui={page:'home',id:'',section:'',query:'',trash:false,template:'romantic',options:{...C.defaultOptions},exportBusy:false,previewUrls:[],previewToken:0};
const current=()=>state.weddings.find(w=>w.id===ui.id),section=()=>current()?.sections.find(s=>s.id===ui.section);const clone=x=>JSON.parse(JSON.stringify(x));
function toast(text,error=false){const e=document.createElement('div');e.className='toast'+(error?' error':'');e.textContent=text;$('#toasts').append(e);setTimeout(()=>e.remove(),error?6500:3500);}
function status(text,error=false){const el=$('#save-status');if(el){el.className='save-status'+(error?' error':'');el.innerHTML=icon(error?'clock':'check')+' '+esc(text);}}
function stash(){try{localStorage.setItem('wedding-web-draft',JSON.stringify({state,base,at:Date.now()}));}catch{status('本机草稿缓存不足，请保持页面打开并备份',true);}}
function touch(w){if(w){w.revision++;w.updatedAt=Date.now();}sequence++;stash();status('正在保存到浏览器…');clearTimeout(timer);timer=setTimeout(()=>flush().catch(e=>toast(e.message,true)),140);}
async function flush(){clearTimeout(timer);if(running)return running;running=(async()=>{while(saved<sequence){if(conflicted)throw new Error('页面版本冲突，请先导出当前草稿，再重新载入');const n=sequence,snapshot=clone(state);try{base=await db.save(snapshot,base);state.revision=base;saved=n;if(n===sequence){localStorage.removeItem('wedding-web-draft');status('已保存到此浏览器');}else stash();}catch(e){if(e.code==='CONFLICT')conflicted=true;stash();status(e.message||'保存失败，请备份后重试',true);throw e;}}})();try{await running;}finally{running=null;}}
async function guard(fn){try{await fn();}catch(e){toast(e.message||'操作未完成，请重试',true);}}
function nav(page){ui.page=page;ui.query='';ui.trash=false;render();window.scrollTo(0,0);}
function field(label,value,field,type='text',attrs=''){const name='f-'+field.replace(/[^a-z0-9]/gi,'-');return `<div class="field"><label for="${name}">${label}</label><input id="${name}" type="${type}" value="${esc(value)}" data-field="${field}" ${attrs}></div>`;}
function area(label,value,field,max=6000){const name='f-'+field.replace(/[^a-z0-9]/gi,'-');return `<div class="field"><label for="${name}">${label}</label><textarea id="${name}" data-field="${field}" maxlength="${max}" rows="3" placeholder="记录${label}…">${esc(value)}</textarea></div>`;}
function shell(content){const names={home:'我的婚礼',editor:'流程编排',music:'音乐库',brand:'个人品牌',backup:'备份与帮助'};return `<aside class="sidebar"><div class="brandmark"><div class="mark">${icon('leaf')}</div><div><b>婚礼流程设计师</b><small>WEDDING ATELIER</small></div></div><nav class="nav" aria-label="主导航">${[['home','calendar','我的婚礼'],['music','music','音乐库'],['brand','brand','个人品牌'],['backup','backup','备份与帮助']].map(([page,name,label])=>`<button data-action="nav" data-page="${page}" class="${ui.page===page||(ui.page==='editor'&&page==='home')?'active':''}">${icon(name)}<span>${label}</span></button>`).join('')}</nav><div class="sidebar-foot"><div class="leaf">${icon('leaf')}</div><b>每一场婚礼，都值得用心。</b><span>免费使用 · 无需微信账号<br>资料保存在此浏览器</span></div></aside><main class="main ${ui.page==='editor'?'editor-main':''}">${ui.page==='editor'?'':`<div class="topbar"><span>工作室 <span style="padding:0 9px;color:#b0b5a9">/</span> ${names[ui.page]||'我的婚礼'}</span><span id="save-status" class="save-status">${icon('check')} ${saved<sequence?'正在保存…':'已保存到此浏览器'}</span></div>`}${content}</main>`;}
function home(){const active=state.weddings.filter(w=>!w.deletedAt),upcoming=active.filter(w=>w.date>=today()).sort((a,b)=>a.date.localeCompare(b.date))[0];const list=state.weddings.filter(w=>ui.trash?!!w.deletedAt:!w.deletedAt).filter(w=>`${w.bride} ${w.groom} ${w.date} ${w.venue} ${w.theme}`.toLowerCase().includes(ui.query.toLowerCase())).sort((a,b)=>b.updatedAt-a.updatedAt);return `<div class="heading"><div><h1 class="serif">我的婚礼</h1><p>从第一首音乐，到最后一次谢幕。</p></div>${btn('new',icon('plus')+' 创建婚礼','primary')}</div><section class="intro"><div class="ribbon"></div><div style="position:relative"><div class="eyebrow">PLAN THE MOMENTS THAT MATTER</div><h2 class="serif">把每个重要时刻，<br>安排得刚刚好。</h2><p>自由编排流程，收藏每一段音乐，<br>把用心准备的仪式，变成清晰、专业的婚礼方案。</p></div><div class="mini-flow"><div><time>18:18</time>主持人开场</div><div><time>18:21</time>新人入场</div><div><time>18:26</time>婚礼问誓</div></div></section><div class="stats"><div class="stat"><span class="stat-icon">${icon('calendar')}</span><div><span class="small muted">婚礼项目</span><b>${active.length} <small style="font-size:.875rem;font-weight:400">场</small></b></div></div><div class="stat"><span class="stat-icon">${icon('music')}</span><div><span class="small muted">收藏的音乐</span><b>${state.assets.filter(a=>a.kind==='music').length} <small style="font-size:.875rem;font-weight:400">首</small></b></div></div><div class="stat"><span class="stat-icon">${icon('leaf')}</span><div><span class="small muted">下一场婚礼</span><b style="font-size:1rem">${upcoming?esc(upcoming.date):'等待一场美好'}</b></div></div></div><div class="toolbar"><div class="tabs"><button data-action="show-active" class="${!ui.trash?'active':''}">全部婚礼 ${active.length}</button><button data-action="show-trash" class="${ui.trash?'active':''}">回收站 ${state.weddings.length-active.length}</button></div><label class="search">${icon('search')}<input type="search" id="search" data-search="home" value="${esc(ui.query)}" placeholder="搜索新人、日期或地点" aria-label="搜索婚礼"></label></div><div class="projects">${list.map(w=>`<article class="project-card"><div class="row between"><span class="badge ${w.date>=today()?'green':''}">${ui.trash?'回收站':w.date>=today()?'筹备中':'已留存'}</span><div class="row" style="gap:0">${ib('project-copy','复制婚礼','copy',`data-id="${w.id}"`)}${ib(ui.trash?'restore':'project-delete',ui.trash?'恢复婚礼':'移入回收站',ui.trash?'restore':'trash',`data-id="${w.id}"`)}</div></div><button class="project-open" data-action="open" data-id="${w.id}"><h3 class="serif">${esc(w.bride)} <span style="color:#a58b58">&</span> ${esc(w.groom)}</h3><div class="date">${icon('calendar')} ${esc(w.date)} <span>· ${esc(w.start)}</span></div><div class="small muted" style="margin-top:10px;min-height:22px">${esc(w.venue||'婚礼地点待定')}</div></button><hr class="divider"><div class="row between"><span class="small muted">${w.sections.length} 个环节 · ${C.total(w)} 分钟</span>${btn(ui.trash?'restore':'project-export',ui.trash?'恢复项目':'导出方案','small light',`data-id="${w.id}"`)}</div></article>`).join('')}</div>${!list.length?`<div class="empty"><div class="empty-art">${icon('leaf')}</div><h3 class="serif">${ui.trash?'回收站是空的':ui.query?'没有找到这场婚礼':'第一场美好，从这里开始'}</h3><p>${ui.trash?'删除的项目可以在这里恢复。':ui.query?'试试其他姓名、日期或地点。':'创建婚礼后，17个标准环节已经为你准备好。'}</p>${!ui.trash&&!ui.query?btn('new',icon('plus')+' 创建我的第一场婚礼','primary'):''}</div>`:''}<p class="page-note">${icon('brand')} 无需注册或购买接口。婚礼、音乐与品牌资料仅保存在当前浏览器，可随时导出备份。</p>`;}
function flowRows(w){return `<button class="insert" data-action="add-section" data-index="0">＋ 在开头添加环节</button>${C.timeline(w).map((s,i)=>`<article class="flow-card ${s.id===ui.section?'selected':''}" draggable="true" data-index="${i}" data-action="select-section" data-id="${s.id}"><span class="drag-handle" title="拖动排序">${icon('grip')}</span><div class="flow-time">${esc(s.start)}</div><div class="grow"><div class="flow-name">${esc(s.name||'未命名环节')}</div><div class="flow-meta">${s.duration} 分钟 · ${s.steps.length} 子步骤${s.music.length?' · '+s.music.length+' 首音乐':''}</div></div><div class="flow-control">${ib('section-up','上移环节','up',`data-index="${i}" ${i===0?'disabled':''}`)}${ib('section-down','下移环节','down',`data-index="${i}" ${i===w.sections.length-1?'disabled':''}`)}</div></article><button class="insert" data-action="add-section" data-index="${i+1}">＋ 插入环节</button>`).join('')}`;}
function details(w,s){if(!s)return '<div class="panel empty-detail">选中左侧环节，<br>在这里记录每一个细节。</div>';return `<section class="panel detail" data-section="${s.id}" aria-label="环节详情滚动区" tabindex="0"><div class="row between"><div><div class="eyebrow" style="margin-bottom:7px">SECTION DETAILS</div><h2>环节详情</h2></div><div class="row" style="gap:3px">${ib('section-copy','复制当前环节','copy')}${ib('section-delete','删除当前环节','trash')}</div></div><div class="form-grid">${field('环节名称',s.name,'s:name','text','maxlength="80"')}${field('预计时长（分钟）',s.duration,'s:duration','number','min="0" max="1440" step="1"')}</div>${field('参与人员',s.people,'s:people','text','maxlength="500" placeholder="新人、父亲、主持人…"')}${area('环节说明',s.description,'s:description')}<div class="section-heading"><h3>子步骤 <span class="section-count">${s.steps.length}</span></h3>${btn('add-step',icon('plus')+' 添加','small light')}</div>${s.steps.map((step,i)=>`<div class="step-row"><div class="row between"><span class="small muted">子步骤 ${i+1}</span><div class="row" style="gap:0">${ib('step-up','上移子步骤','up',`data-id="${step.id}" ${!i?'disabled':''}`)}${ib('step-down','下移子步骤','down',`data-id="${step.id}" ${i===s.steps.length-1?'disabled':''}`)}${ib('step-delete','删除子步骤','trash',`data-id="${step.id}"`)}</div></div><input class="control" aria-label="子步骤名称" value="${esc(step.name)}" maxlength="1000" data-field="step:${step.id}:name"><div class="row between"><span class="helper">参考时长，不重复计入总时长</span><input type="number" class="control" min="0" max="1440" aria-label="子步骤时长" value="${step.duration}" data-field="step:${step.id}:duration"></div></div>`).join('')}${!s.steps.length?'<p class="helper">把入场、交接、登台拆成更清晰的小步骤。</p>':''}<div class="section-heading"><h3>音乐与播放提示</h3>${btn('choose-music',icon('plus')+' 关联音乐','small light')}</div>${s.music.map(m=>{const a=state.assets.find(a=>a.id===m.assetId);return `<div class="music-link"><div class="row between"><strong>${icon('music')} ${esc(a?.name||'音乐文件不可用')}</strong><div class="row" style="gap:0">${ib('play','试听此音乐','play',`data-id="${m.assetId}"`)}${ib('unlink','解除音乐关联','close',`data-id="${m.id}"`)}</div></div>${area('播放提示',m.cue,'link:'+m.id+':cue',1000)}${field('飞书试听链接（选填）',m.previewUrl||'','link:'+m.id+':previewUrl','url','maxlength="2048" placeholder="https://你的空间.feishu.cn/file/…"')}<p class="helper">粘贴已上传音乐的飞书分享网址。${a?.previewUrl?'留空使用音乐库中已保存的链接。':'导出Excel时，音乐名称会链接到这个地址。'}请先在飞书开启新人可访问的分享权限。</p></div>`;}).join('')}${!s.music.length?'<p class="helper">可添加多首音乐，并分别记录播放提示和飞书试听链接。</p>':''}<div class="section-heading"><h3>分类备注</h3><span class="helper">导出时可独立选择</span></div><div class="note-grid">${[['couple','新人须知'],['planner','管家及督导备注'],['host','主持人备注'],['other','其他备注']].map(([key,label])=>area(label,s.notes[key],'s:notes.'+key)).join('')}</div></section>`;}
function editor(){const w=current();if(!w){ui.page='home';return home();}if(!w.sections.some(s=>s.id===ui.section))ui.section=w.sections[0]?.id||'';return `<div class="heading editor-heading"><div class="editor-title"><h1 class="serif">${esc(w.bride)} & ${esc(w.groom)}</h1><p>${esc(w.date)} · ${esc(w.venue||'婚礼地点待定')}${w.theme?' · '+esc(w.theme):''}</p></div><div class="actions"><span id="save-status" class="save-status">${icon('check')} ${saved<sequence?'正在保存…':'已保存到此浏览器'}</span>${btn('edit-info',icon('settings')+' 基本信息')}${btn('export',icon('download')+' 导出方案','primary')}</div></div><div class="editor-info"><div class="summary-duration"><span class="small muted">预计总时长</span><span class="big"><span data-total>${C.total(w)}</span><small>分钟</small></span></div><div class="summary-start"><label for="start-time">开始时间</label><input class="control" id="start-time" type="time" value="${w.start}" data-field="w:start"></div><span class="small muted summary-count"><b data-count>${w.sections.length}</b> 个环节</span><span class="helper sort-hint">拖动卡片或用上下按钮排序</span></div><div class="editor" data-wedding="${w.id}"><div class="flow-column"><div class="flow-list" aria-label="婚礼流程" tabindex="0">${flowRows(w)}</div>${!w.sections.length?'<div class="empty"><h3>为这场婚礼添加第一个环节</h3></div>':''}</div>${details(w,section())}</div>`;}
function refs(assetId){return state.weddings.filter(w=>w.sections.some(s=>s.music.some(m=>m.assetId===assetId)));}
function music(){const assets=state.assets.filter(a=>a.kind==='music'&&a.name.toLowerCase().includes(ui.query.toLowerCase()));return `<div class="heading"><div><h1 class="serif">音乐库</h1><p>为每个重要瞬间，找到恰好的旋律。</p></div>${btn('import-music',icon('plus')+' 导入音乐','primary')}</div><div class="notice">音乐直接保存在这个浏览器，不上传服务器。支持 MP3、M4A、WAV、OGG，单首不超过20MB；同一首音乐可在不同婚礼中重复使用。</div>${musicDrop()}<div class="toolbar"><span class="small muted">共 ${state.assets.filter(a=>a.kind==='music').length} 首音乐</span><label class="search">${icon('search')}<input id="search" data-search="music" type="search" value="${esc(ui.query)}" placeholder="搜索音乐名称" aria-label="搜索音乐"></label></div><div class="music-grid">${assets.map(a=>`<article class="panel music-card"><div class="row"><div class="music-symbol">${icon('music')}</div><div class="grow"><h3>${esc(a.name)}</h3><p class="helper" style="margin-top:7px">${esc(a.extension.toUpperCase())} · ${(a.size/1024/1024).toFixed(1)} MB · ${a.duration?Math.round(a.duration)+'秒':'试听时读取时长'}</p></div></div><div class="row between" style="margin-top:19px"><span class="small muted">${refs(a.id).length?'用于 '+refs(a.id).length+' 场婚礼':'尚未关联婚礼'}</span><div class="row" style="gap:1px">${ib('music-url','设置飞书试听链接','file',`data-id="${a.id}"`)}${ib('music-rename','重命名音乐','settings',`data-id="${a.id}"`)}${ib('music-delete','删除音乐','trash',`data-id="${a.id}"`)}</div></div>${btn('play',icon('play')+' 试听','light',`data-id="${a.id}"`)}<p class="helper music-url-status">${a.previewUrl?'已设置飞书试听链接':'尚未设置飞书试听链接'}</p></article>`).join('')}</div>${!assets.length?`<div class="empty"><div class="empty-art">${icon('headphones')}</div><h3 class="serif">${ui.query?'没有找到这首音乐':'从一首喜欢的音乐开始'}</h3><p>${ui.query?'换个名称再搜索。':'导入音频文件，为婚礼流程配上专属的声音。'}</p>${!ui.query?btn('import-music',icon('plus')+' 导入音乐','primary'):''}</div>`:''}`;}
function brandPreview(){return `<div class="eyebrow" style="margin-bottom:27px">YOUR SIGNATURE</div>${brandUrl?`<img src="${brandUrl}" alt="品牌Logo" style="width:${logoInfo?C.logoDimensions(logoInfo.width,logoInfo.height,state.brand.logoScale).width:180}px;max-width:100%;max-height:none;height:auto">`:''}<h3>${esc(state.brand.name||'你的婚礼工作室')}</h3><p>${esc(state.brand.contact||'婚礼仪式策划与主持')}</p><div style="width:40px;border-top:1px solid #bca679;margin:23px 0 3px"></div><p>${esc(state.brand.signoff||'愿每一场相遇，都成为温暖的回忆。')}</p>`;}
function logoControls(){if(!brandUrl||!logoInfo)return '';const size=C.logoDimensions(logoInfo.width,logoInfo.height,state.brand.logoScale),scale=C.logoScale(state.brand.logoScale);return `<div class="logo-size"><div class="field"><label for="logo-scale">Logo大小（%）</label><div class="row"><input id="logo-scale" data-field="b:logoScale" type="range" min="25" max="300" step="1" value="${scale}"><input id="logo-scale-number" aria-label="Logo大小百分比" data-field="b:logoScale" type="number" min="25" max="300" step="1" value="${scale}" style="width:95px"></div></div><p class="helper" id="logo-size-info">${logoSizeText()}</p>${btn('download-logo','下载原图','small light')}</div>`;}
function logoSizeText(){if(!logoInfo)return '';const size=C.logoDimensions(logoInfo.width,logoInfo.height,state.brand.logoScale);return `原图 ${logoInfo.width} × ${logoInfo.height} 像素 · 导出画面 ${Math.round(size.width)} × ${Math.round(size.height)} 像素（高清图片基准）。${size.upscaled?'当前尺寸超过原图像素，放大不会增加细节。':'保持原始比例，从原图直接绘制。'} Word和PDF内嵌原图，PNG采用无损编码。`;}
function brand(){return `<div class="heading"><div><h1 class="serif">个人品牌</h1><p>在每一份用心的方案上，留下你的名字。</p></div></div><div class="brand-layout"><section class="panel brand-form"><h2 style="font-size:1.2rem">品牌信息</h2><p class="helper" style="margin-top:8px">修改后自动保存，导出时可选择显示或隐藏。</p>${field('主持人或工作室名称',state.brand.name,'b:name','text','maxlength="80" placeholder="你的品牌名称"')}${field('联系方式（选填）',state.brand.contact,'b:contact','text','maxlength="200"')}${area('默认落款',state.brand.signoff,'b:signoff',500)}<div class="field"><label>品牌Logo</label><div class="row wrap">${btn('import-logo',icon('plus')+(brandUrl?' 更换Logo':' 上传Logo'),'small')}${brandUrl?btn('remove-logo','移除Logo','small danger'):''}</div><span class="helper">PNG / JPG · 不超过20MB · 保留原文件和透明背景</span></div>${logoControls()}</section><aside class="brand-preview" id="brand-preview">${brandPreview()}</aside></div>`;}
function backup(){return `<div class="heading"><div><h1 class="serif">备份与帮助</h1><p>把重要的准备，妥善留在自己手中。</p></div></div><div class="backup-layout"><section class="panel backup-card">${icon('backup')}<h2 class="serif">完整备份</h2><p>将全部婚礼、环节、备注、音乐文件和品牌Logo打包为一个ZIP。保存到你信任的位置，下次可以完整导入。</p>${btn('backup',icon('download')+' 导出全部资料','primary')}<p class="helper" style="margin-top:17px;margin-bottom:0">备份仅生成在浏览器中，不会上传到服务器。音乐较多时请耐心等待。</p></section><section class="panel backup-card">${icon('restore')}<h2 class="serif">从备份恢复</h2><p>导入本工具生成的备份ZIP。婚礼会作为新项目加入，现有项目会保留；相同音乐自动复用。</p>${btn('import-backup',icon('plus')+' 导入备份文件')}<p class="helper" style="margin-top:17px;margin-bottom:0">换电脑或浏览器时，先在原设备备份，再在新设备导入。</p></section></div><section class="panel faq"><div class="row between"><h2 style="font-size:1.2rem">浏览器存储</h2><span class="small muted" id="storage-label">正在读取用量…</span></div><div class="storage-bar"><div class="storage-fill" id="storage-fill" style="width:0"></div></div><p class="helper">资料保存在当前网址、当前浏览器的本地空间。清理网站数据、使用无痕模式，或更换设备，都可能无法读到原来的资料，请定期备份。</p><div style="margin-top:16px">${btn('protect-storage','申请持久存储保护','small light')}${conflicted?' '+btn('draft-backup','导出当前未同步草稿','small')+' '+btn('reload-saved','重新载入已保存资料','small'):''}</div></section><section class="panel faq"><h2 style="font-size:1.2rem;margin-bottom:10px">使用说明</h2><details><summary>免费版包含哪些功能？</summary><p>创建婚礼、17个标准环节、自定义排序、子步骤、分类备注、音乐导入与试听、个人品牌，以及Word、PDF和两种高清图片导出都可在浏览器中使用，无需微信账号或付费API。</p></details><details><summary>手机和电脑的数据会自动同步吗？</summary><p>当前版本不使用云端数据库，资料分别保存在各自浏览器中。请通过“完整备份”和“从备份恢复”在设备间迁移。不要依赖浏览器同步账号来同步婚礼文件。</p></details><details><summary>怎么把方案交给新人或婚礼团队？</summary><p>在婚礼编辑页打开“导出方案”，选择模板及内容。Word可编辑，PDF方便正式交付，两种PNG模板适合发群沟通。图片与PDF采用单页左右分栏，内容较多时页面自动增高。Excel音乐清单按流程排列，蓝色音乐名称可打开已填写的飞书分享链接。</p></details><details><summary>PDF正文为什么不能直接复制？</summary><p>为保证不同设备中文与版式一致，PDF使用高清页面图片。需要编辑和复制文字时，请导出Word。所有格式读取同一份流程数据。</p></details><details><summary>会影响以前的微信小程序吗？</summary><p>网页版是独立工程，不会修改微信小程序或其数据。微信本机缓存无法由网页直接读取；已有婚礼可在网页版重新整理，或通过本网页的备份格式导入。</p></details></section>`;}
function render(){if(!state)return;const oldScroll={left:$('.flow-list')?.scrollTop||0,right:$('.detail')?.scrollTop||0,section:$('.detail')?.dataset.section,wedding:$('.editor')?.dataset.wedding};document.body.classList.toggle('editor-mode',ui.page==='editor');const focus=document.activeElement?.id,start=document.activeElement?.selectionStart;$('#app').innerHTML=shell(({home,editor,music,brand,backup}[ui.page]||home)());if(oldScroll.wedding===ui.id&&ui.page==='editor'){if($('.flow-list'))$('.flow-list').scrollTop=oldScroll.left;if($('.detail')&&oldScroll.section===ui.section)$('.detail').scrollTop=oldScroll.right;}if(saved<sequence)status(conflicted?'页面版本冲突，请先备份': '正在保存…',conflicted);if(focus){const input=document.getElementById(focus);if(input){input.focus({preventScroll:true});try{input.setSelectionRange(start,start);}catch{}}}if(ui.page==='backup')db.storage().then(e=>{if($('#storage-label'))$('#storage-label').textContent=`已用 ${(e.usage/1024/1024).toFixed(1)} MB${e.quota?' / 约 '+(e.quota/1024/1024/1024).toFixed(1)+' GB':''}`;if($('#storage-fill'))$('#storage-fill').style.width=Math.max(2,Math.min(100,e.usage/(e.quota||1)*100))+'%';});}
function refreshFlow(){const w=current();if(!w)return;const list=$('.flow-list');if(list){const top=list.scrollTop;list.innerHTML=flowRows(w);list.scrollTop=top;}document.querySelectorAll('[data-total]').forEach(e=>e.textContent=C.total(w));}
function closeModal(){if(ui.exportBusy){toast('正在生成文件，请稍候');return;}$('#modal').close();ui.previewToken++;for(const url of ui.previewUrls)URL.revokeObjectURL(url);ui.previewUrls=[];const callback=modalSubmit;modalSubmit=null;if(callback?.cancel)callback.cancel();}
function modal(title,content,submit,wide=false){const el=$('#modal');el.className=wide?'modal-wide':'';el.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2>${ib('close-modal','关闭对话框','close')}</div><form id="modal-form" class="modal-body">${content}</form>`;modalSubmit=submit;if(!el.open)el.showModal();setTimeout(()=>el.querySelector('input:not([type=checkbox]),textarea,select')?.focus(),30);}
function confirmBox(title,text){return new Promise(resolve=>{const submit=async()=>{modalSubmit=null;$('#modal').close();resolve(true);};submit.cancel=()=>resolve(false);modal(title,`<p class="confirm-text">${esc(text)}</p><div class="modal-actions">${btn('close-modal','取消')}<button class="btn primary" type="submit">确认</button></div>`,submit);});}
function promptBox(title,value=''){return new Promise(resolve=>{const submit=async form=>{const input=form.elements.value.value.trim();if(!input)throw new Error('请填写内容');modalSubmit=null;$('#modal').close();resolve(input);};submit.cancel=()=>resolve(null);modal(title,`<div class="field"><label for="prompt-value">${esc(title)}</label><input id="prompt-value" name="value" value="${esc(value)}" maxlength="120" required></div><div class="modal-actions">${btn('close-modal','取消')}<button type="submit" class="btn primary">保存</button></div>`,submit);});}
function weddingForm(existing){const w=existing||{bride:'',groom:'',date:today(),start:'18:18',venue:'',theme:''};modal(existing?'婚礼基本信息':'创建一场婚礼',`<p class="helper" style="margin-top:17px">${existing?'婚礼信息修改后，导出方案也会同步更新。':'填写新人信息，17个标准环节将自动为你准备好。'}</p><div class="form-grid">${[['bride','新娘姓名','text',40],['groom','新郎姓名','text',40],['date','婚礼日期','date',10],['start','仪式开始时间','time',5]].map(([key,label,type,max])=>`<div class="field"><label for="new-${key}">${label} *</label><input id="new-${key}" name="${key}" type="${type}" value="${esc(w[key])}" maxlength="${max}" required></div>`).join('')}</div>${[['venue','婚礼地点',200],['theme','婚礼主题',100]].map(([key,label,max])=>`<div class="field"><label for="new-${key}">${label}</label><input id="new-${key}" name="${key}" maxlength="${max}" value="${esc(w[key])}" placeholder="${key==='venue'?'酒店 · 宴会厅':'为你们的故事取一个名字'}"></div>`).join('')}<div class="modal-actions">${btn('close-modal','取消')}<button type="submit" class="btn primary">${existing?'保存信息':'创建并编排流程'}</button></div>`,async form=>{const info=Object.fromEntries(new FormData(form));if(existing){const next={...existing,...info};C.validateWedding(next);Object.assign(existing,info);touch(existing);}else{if(state.weddings.length>=100)throw new Error('最多保存100场婚礼（含回收站）');const next=C.createWedding(info,'web-local');state.weddings.push(next);ui.id=next.id;ui.section=next.sections[0]?.id||'';ui.page='editor';touch(next);}await flush();closeModal();render();window.scrollTo(0,0);});}
function addSection(index){const w=current();if(w.sections.length>=80)throw new Error('每场婚礼最多80个主环节');modal('添加婚礼环节',`<div class="field"><label for="preset-name">从标准环节开始</label><select name="preset" id="preset-name"><option value="">完全自定义环节</option>${C.presets.map(name=>`<option value="${esc(name)}">${esc(name)}</option>`).join('')}</select></div><div class="field"><label for="custom-name">环节名称</label><input id="custom-name" name="custom" placeholder="自定义名称，或使用上方所选环节" maxlength="80"></div><div class="field"><label for="section-duration">预计时长（分钟）</label><input id="section-duration" name="duration" type="number" min="0" max="1440" value="2" required></div><div class="modal-actions">${btn('close-modal','取消')}<button type="submit" class="btn primary">添加到流程</button></div>`,async form=>{const name=form.elements.custom.value.trim()||form.elements.preset.value;if(!name)throw new Error('请填写名称或选择标准环节');const s=C.section(name,Number(form.elements.duration.value));w.sections.splice(index,0,s);ui.section=s.id;touch(w);closeModal();render();});}
async function fileUrl(id){if(urls.has(id))return urls.get(id);const blob=await db.getFile(id);if(!blob)throw new Error('文件未找到，请从完整备份恢复');const url=URL.createObjectURL(blob);urls.set(id,url);return url;}
async function loadBrand(){logoInfo=null;if(state.brand.logo){brandUrl=await fileUrl(state.brand.logo);const pic=await createImageBitmap(await db.getFile(state.brand.logo));logoInfo={width:pic.width,height:pic.height};pic.close();}else brandUrl='';}
async function play(id){const asset=state.assets.find(a=>a.id===id&&a.kind==='music');if(!asset)throw new Error('这首音乐不存在');const audio=$('#player audio');audio.dataset.asset=id;if(audio.dataset.current!==id){audio.src=await fileUrl(id);audio.dataset.current=id;}$('#player .player-name').textContent=asset.name;$('#player').hidden=false;await audio.play();}
async function fileHash(blob){if(crypto?.subtle){const bytes=await blob.arrayBuffer();return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),x=>x.toString(16).padStart(2,'0')).join('');}return 'crc-'+await WZip.crc(blob)+'-'+blob.size;}
async function checkAudio(file,ext){const b=new Uint8Array(await file.slice(0,16).arrayBuffer()),ascii=(a,z)=>new TextDecoder().decode(b.slice(a,z));const valid=ext==='mp3'?(ascii(0,3)==='ID3'||b[0]===255&&(b[1]&224)===224):ext==='m4a'?ascii(4,8)==='ftyp':ext==='wav'?ascii(0,4)==='RIFF'&&ascii(8,12)==='WAVE':ext==='ogg'?ascii(0,4)==='OggS':false;if(!valid)throw new Error('音频内容与文件格式不符：'+file.name);}
async function importMusic(files){if(ui.musicBusy)throw new Error('音乐正在导入，请稍候再添加');ui.musicBusy=true;try{let added=0,duplicates=0;for(const file of files){if(state.assets.filter(a=>a.kind==='music').length>=200)throw new Error('音乐库最多200首');const ext=file.name.split('.').pop().toLowerCase();if(!['mp3','m4a','wav','ogg'].includes(ext)||file.size>20*1024*1024||file.size===0)throw new Error('请导入20MB以内的MP3、M4A、WAV或OGG');await checkAudio(file,ext);const hash=await fileHash(file);if(state.assets.some(a=>a.kind==='music'&&a.hash===hash)){duplicates++;continue;}const id=C.uid();await db.putFile(id,file);state.assets.push({id,owner:'web-local',kind:'music',fileId:id,name:file.name.replace(/\.[^.]+$/,'').slice(0,120),extension:ext,size:file.size,duration:0,hash,mime:file.type||({mp3:'audio/mpeg',m4a:'audio/mp4',wav:'audio/wav',ogg:'audio/ogg'}[ext]),createdAt:Date.now()});added++;touch();}await flush();toast(`导入 ${added} 首音乐${duplicates?'，已复用 '+duplicates+' 首相同文件':''}`);if($('#modal').open&&$('#modal').dataset.music==='yes')await chooseMusic();else render();}finally{ui.musicBusy=false;}}
async function importLogo(file){if(!['image/png','image/jpeg'].includes(file.type)||!file.size||file.size>20*1024*1024)throw new Error('请使用20MB以内的PNG或JPG');const pic=await createImageBitmap(file);if(pic.width*pic.height>32000000){pic.close();throw new Error('Logo超过3200万像素，请使用尺寸较小的原图');}pic.close();const id=C.uid();await db.putFile(id,file);const old=state.brand.logo;state.assets.push({id,kind:'logo',name:file.name,size:file.size,mime:file.type,hash:await fileHash(file),extension:file.type==='image/png'?'png':'jpg'});state.brand.logo=id;touch();await flush();if(old){state.assets=state.assets.filter(a=>a.id!==old);touch();await flush();await db.removeFile(old);}await loadBrand();render();toast('品牌Logo已保存');}
function editMusicUrl(id){const asset=state.assets.find(a=>a.id===id&&a.kind==='music');if(!asset)throw new Error('音乐不存在');modal('设置飞书试听链接',`<p class="helper" style="margin-top:17px">先自行把“${esc(asset.name)}”上传至飞书，并开启新人可访问的分享权限，再复制网址到这里。</p><div class="field"><label for="music-preview-url">飞书分享网址</label><input id="music-preview-url" name="url" type="url" value="${esc(asset.previewUrl||'')}" maxlength="2048" placeholder="https://你的空间.feishu.cn/file/…"></div><div class="modal-actions">${btn('close-modal','取消')}<button class="btn primary" type="submit">保存链接</button></div>`,async form=>{asset.previewUrl=WMusicSheet.previewUrl(form.elements.url.value);touch();await flush();closeModal();render();toast('飞书试听链接已保存');});$('#modal').dataset.music='';}
async function chooseMusic(){const s=section();if(!s)throw new Error('请先选择一个环节');if(s.music.length>=20)throw new Error('每个环节最多关联20首音乐');const items=state.assets.filter(a=>a.kind==='music');modal('为这个环节选择音乐',`<p class="helper" style="margin-top:17px">选择音乐后可填写播放提示和飞书试听链接，用于生成给新人的Excel音乐清单。</p>${musicDrop()}<div class="select-list">${items.map(a=>`<button type="button" class="select-item" data-action="link-music" data-id="${a.id}"><span>${icon('music')} ${esc(a.name)}</span><span class="small muted">选择</span></button>`).join('')}${!items.length?'<p class="confirm-text">音乐库里还没有音乐，可以先导入一首。</p>':''}</div><div class="modal-actions">${btn('import-music',icon('plus')+' 导入新音乐')}</div>`,null);$('#modal').dataset.music='yes';}
function exportSettings(){const fields=[['time','预计时间'],['description','环节说明'],['steps','子步骤'],['couple','新人须知'],['planner','管家及督导备注'],['host','主持人备注'],['other','其他备注'],['music','音乐名称与提示'],['brand','品牌信息与Logo']];return `<div class="export-layout"><div class="export-settings"><div><div class="field-label" style="margin-bottom:11px">图片与PDF风格</div>${[['romantic','浪漫婚礼时间轴','奶油白、香槟金与植物线稿'],['professional','高级婚礼策划案','深绿灰、清晰分工与执行细节']].map(([key,title,sub])=>`<button type="button" class="template-option ${ui.template===key?'active':''}" data-action="template" data-value="${key}" style="margin-bottom:10px"><b>${title}</b><span>${sub}</span></button>`).join('')}</div><div><div class="field-label" style="margin-bottom:7px">选择导出内容</div>${fields.map(([key,label])=>`<label class="check-row"><input type="checkbox" data-export-option="${key}" ${ui.options[key]?'checked':''}>${label}</label>`).join('')}</div><div class="field"><label for="export-format">文件格式</label><select id="export-format"><option value="png">完整流程单图（PNG）</option><option value="pdf">正式交付（PDF）</option><option value="docx">可编辑方案（Word）</option><option value="xlsx">流程音乐清单（Excel含试听链接）</option></select></div><p class="helper">图片与PDF采用单页双栏，顺序为先左后右；内容较多时自动增高。Excel按流程排列全部音乐，已填写链接的音乐名称可点击试听。Word可编辑。版本按每场婚礼导出次数递增，预览不计次。</p><div class="export-actions">${btn('preview-export','预览排版','light')}${btn('download-export',icon('download')+' 导出文件','primary')}</div><p class="helper" id="export-status" role="status">文件在此浏览器内生成，不上传资料。</p></div><div><div class="helper" style="margin-bottom:12px">图片 / PDF排版预览</div><div class="export-preview" id="export-preview"><div class="export-placeholder">${icon('file')}<p style="margin-top:16px">选择模板和显示内容，<br>点击“预览排版”确认最终效果。</p></div></div></div></div>`;}
async function openExport(id){if(id){ui.id=id;}const w=current();if(!w||w.deletedAt)throw new Error('请先选择有效婚礼');await flush();C.validateWedding(w);modal('导出婚礼方案',exportSettings(),null,true);$('#modal').dataset.music='';}
function invalidatePreview(){ui.previewToken++;for(const url of ui.previewUrls)URL.revokeObjectURL(url);ui.previewUrls=[];if($('#export-preview'))$('#export-preview').innerHTML='<div class="export-placeholder">内容选择已更新，请重新预览排版。</div>';}
function exportProgress(text){if($('#export-status'))$('#export-status').textContent=text;}
async function snapshot(){await flush();const w=current();C.validateWedding(w);const ids=new Set(state.assets.filter(a=>a.kind==='music').map(a=>a.id));if(w.sections.some(s=>s.music.some(m=>!ids.has(m.assetId))))throw new Error('存在丢失的音乐关联，请先修复或解除关联');return C.project(clone(w),clone(state.assets),clone(state.brand),ui.options,C.nextExportVersion(w,state.exports));}
async function previewExport(){if(ui.exportBusy)return;ui.exportBusy=true;const token=++ui.previewToken;try{const p=await snapshot(),logo=p.brand.logo?await db.getFile(p.brand.logo):null;exportProgress('正在加载中文字体并排版…');const pages=await WExport.images(p,ui.template,logo,(n,total)=>exportProgress(`正在生成第 ${n} / ${total} 页…`));if(token!==ui.previewToken)return;for(const url of ui.previewUrls)URL.revokeObjectURL(url);ui.previewUrls=pages.map(b=>URL.createObjectURL(b));$('#export-preview').innerHTML=ui.previewUrls.map((url,i)=>`<img src="${url}" alt="婚礼方案第${i+1}页" loading="lazy">`).join('');exportProgress(`预览完成，共 ${pages.length} 页。下一次导出将使用流程版本 ${p.exportVersion}，预览不计次。`);}finally{ui.exportBusy=false;}}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name.replace(/[\\/:*?"<>|]/g,'_');document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
async function recordExport(p,entry){
 await flush();
 const wedding=state.weddings.find(w=>w.id===p.id);
 if(!wedding||C.nextExportVersion(wedding,state.exports)!==p.exportVersion)throw new Error('导出次数已变化，请重新生成文件');
 const next=clone(state);next.weddings.find(w=>w.id===p.id).exportCount=p.exportVersion;
 next.exports=[entry,...next.exports].slice(0,100);
 const captured=sequence;
 running=(async()=>{const revision=await db.save(next,base);base=revision;state.revision=revision;
  state.weddings.find(w=>w.id===p.id).exportCount=p.exportVersion;state.exports=[entry,...state.exports].slice(0,100);saved=captured;
  if(saved===sequence){localStorage.removeItem('wedding-web-draft');status('已保存到此浏览器');}else stash();
 })();
 try{await running;}catch(error){if(error.code==='CONFLICT')conflicted=true;stash();status('导出记录未保存，请重新载入后重试',true);throw error;}finally{running=null;}
 if(saved<sequence)await flush();
}
async function downloadExport(){if(ui.exportBusy)return;ui.exportBusy=true;try{const p=await snapshot(),exportWedding=clone(current()),exportAssets=clone(state.assets),format=$('#export-format').value,logo=format!=='xlsx'&&p.brand.logo?await db.getFile(p.brand.logo):null;const filename=`${p.title} ${p.date} 婚礼流程`;exportProgress('正在生成文件，请保持页面打开…');let file,name;if(format==='xlsx'){file=await WMusicSheet.create(exportWedding,exportAssets,p.exportVersion);name=`${p.title} ${p.date} 婚礼音乐清单.xlsx`;}else if(format==='docx'){file=await WExport.word(p,logo);name=filename+'.docx';}else if(format==='pdf'){file=await WExport.pdf(p,ui.template,logo,(n,total)=>exportProgress(`正在生成PDF第 ${n} / ${total} 页…`));name=filename+'.pdf';}else{const pages=await WExport.images(p,ui.template,logo,(n,total)=>exportProgress(`正在生成图片第 ${n} / ${total} 页…`));if(pages.length===1){file=pages[0];name=filename+'.png';}else{file=await WZip.create(pages.map((blob,i)=>({name:`${filename}-${String(i+1).padStart(2,'0')}.png`,blob})));name=filename+'-全部图片.zip';}}await recordExport(p,{id:C.uid(),weddingId:p.id,format,template:ui.template,createdAt:Date.now(),name,exportVersion:p.exportVersion});download(file,name);invalidatePreview();exportProgress(`已生成流程版本 ${p.exportVersion}，下次导出为 ${p.exportVersion+1}。请在浏览器下载列表查看文件。`);toast(`婚礼方案已生成 · 流程版本 ${p.exportVersion}`);}finally{ui.exportBusy=false;}}
async function backupAll(){if(!conflicted)await flush();const snapshot=clone(state),entries=[{name:'manifest.json',blob:new Blob([JSON.stringify({format:'wedding-flow-designer',schemaVersion:1,createdAt:new Date().toISOString(),workspace:snapshot},null,2)],{type:'application/json'})}];toast('正在打包婚礼和音乐，请稍候…');for(const a of snapshot.assets){const blob=await db.getFile(a.id);if(!blob)throw new Error('备份未生成：文件丢失 '+a.name);entries.push({name:'files/'+a.id,blob});}download(await WZip.create(entries),`婚礼流程设计师-完整备份-${today()}.zip`);toast('完整备份已生成，请妥善保存');}
async function restoreBackup(file){if(!await confirmBox('导入完整备份',`将从“${file.name}”新增婚礼和音乐，现有项目不会被覆盖。若尚未设置品牌，也会恢复备份中的品牌信息。`))return;await flush();const archive=await WZip.read(file),manifestBlob=await archive.get('manifest.json');if(manifestBlob.size>100*1024*1024)throw new Error('备份清单过大');const manifest=JSON.parse(await manifestBlob.text());if(manifest.format!=='wedding-flow-designer'||manifest.schemaVersion!==1)throw new Error('不支持的备份版本');const incoming=manifest.workspace;if(!incoming||!Array.isArray(incoming.weddings)||!Array.isArray(incoming.assets)||incoming.weddings.length>100||incoming.assets.length>250)throw new Error('备份数据结构无效');if(state.weddings.length+incoming.weddings.length>100)throw new Error('导入后超过100场婚礼上限');const safeId=id=>typeof id==='string'&&/^[a-zA-Z0-9_-]{1,80}$/.test(id);const next=clone(state),files=[],mapping=new Map();let duplicate=0;for(const a of incoming.assets){if(!safeId(a.id)||!['music','logo'].includes(a.kind)||typeof a.name!=='string'||a.name.length>200||typeof a.hash!=='string'||a.hash.length>128)throw new Error('备份资产信息无效');const original=next.assets.find(x=>x.kind===a.kind&&x.hash===a.hash);if(original){if(!original.previewUrl&&a.previewUrl)original.previewUrl=WMusicSheet.previewUrl(a.previewUrl);mapping.set(a.id,original.id);duplicate++;continue;}const blob=await archive.get('files/'+a.id);if(blob.size>20*1024*1024)throw new Error('备份中的文件超过大小限制');if(a.kind==='music')await checkAudio(Object.assign(blob,{name:a.name}),a.extension);else{if(!['png','jpg'].includes(a.extension))throw new Error('Logo格式无效');const pic=await createImageBitmap(blob);pic.close();}const id=next.assets.some(x=>x.id===a.id)?C.uid():a.id;mapping.set(a.id,id);const mime=a.kind==='logo'?(a.extension==='png'?'image/png':'image/jpeg'):({mp3:'audio/mpeg',m4a:'audio/mp4',wav:'audio/wav',ogg:'audio/ogg'}[a.extension]);const record={id,owner:'web-local',kind:a.kind,name:a.name,extension:a.extension,mime,hash:a.hash,size:blob.size,duration:Number.isFinite(a.duration)?Math.max(0,a.duration):0,previewUrl:WMusicSheet.previewUrl(a.previewUrl||''),fileId:id,createdAt:Date.now()};next.assets.push(record);files.push({id,blob:new Blob([blob],{type:mime})});}
for(const raw of incoming.weddings){C.validateWedding(raw);if(!safeId(raw.id)||raw.sections.some(s=>!safeId(s.id)||s.steps.some(t=>!safeId(t.id))||s.music.some(m=>!safeId(m.id))))throw new Error('备份中的流程编号无效');const w=C.copyWedding(raw,true,Array.isArray(incoming.exports)?incoming.exports:[]);w.owner='web-local';for(const s of w.sections)for(const m of s.music){if(!mapping.has(m.assetId))throw new Error('备份中缺少被引用的音乐');m.assetId=mapping.get(m.assetId);}next.weddings.push(w);}if(!state.brand.name&&!state.brand.logo&&incoming.brand){const b=incoming.brand;if(['name','contact','signoff'].some(k=>typeof b[k]!=='string')||b.name.length>80||b.contact.length>200||b.signoff.length>500)throw new Error('备份品牌信息无效');next.brand={name:b.name,contact:b.contact,signoff:b.signoff,logo:b.logo?mapping.get(b.logo)||'':'',logoScale:C.logoScale(b.logoScale)};}if(next.assets.filter(a=>a.kind==='music').length>200)throw new Error('导入后超过200首音乐');base=await db.save(next,base,files);next.revision=base;state=next;sequence=saved=0;localStorage.removeItem('wedding-web-draft');await loadBrand();ui.page='home';ui.query='';render();toast(`已导入 ${incoming.weddings.length} 场婚礼${duplicate?'，复用 '+duplicate+' 个文件':''}`);}
const actions={
nav:el=>nav(el.dataset.page),new:()=>weddingForm(),open:el=>{const w=state.weddings.find(w=>w.id===el.dataset.id);if(w.deletedAt){toast('请先从回收站恢复这场婚礼');return;}ui.id=w.id;ui.section=w.sections[0]?.id||'';ui.page='editor';ui.query='';render();window.scrollTo(0,0);},'show-active':()=>{ui.trash=false;render();},'show-trash':()=>{ui.trash=true;render();},
'edit-info':()=>weddingForm(current()),'project-copy':el=>{if(state.weddings.length>=100)throw new Error('最多100场婚礼');const w=C.copyWedding(state.weddings.find(w=>w.id===el.dataset.id));state.weddings.push(w);touch(w);render();toast('已复制婚礼，音乐文件可继续共用');},
'project-delete':async el=>{const w=state.weddings.find(w=>w.id===el.dataset.id);if(await confirmBox('移入回收站',`将“${w.bride} & ${w.groom}”移入回收站？可随时恢复，音乐文件会保留。`)){w.deletedAt=Date.now();touch(w);render();}},
restore:el=>{const w=state.weddings.find(w=>w.id===el.dataset.id);w.deletedAt=null;touch(w);render();toast('婚礼项目已恢复');},
'select-section':el=>{ui.section=el.dataset.id;render();},'add-section':el=>addSection(Number(el.dataset.index)),
'section-up':el=>{const w=current(),i=Number(el.dataset.index);if(i>0){w.sections=C.move(w.sections,i,i-1);touch(w);refreshFlow();}},
'section-down':el=>{const w=current(),i=Number(el.dataset.index);if(i<w.sections.length-1){w.sections=C.move(w.sections,i,i+1);touch(w);refreshFlow();}},
'section-copy':()=>{const w=current(),s=section();if(w.sections.length>=80)throw new Error('最多80个主环节');const copy=C.copySection(s);w.sections.splice(w.sections.indexOf(s)+1,0,copy);ui.section=copy.id;touch(w);render();},
'section-delete':async()=>{const w=current(),s=section();if(await confirmBox('删除环节',`删除“${s.name}”及其子步骤和音乐关联？音乐库中的原文件会保留。`)){w.sections=w.sections.filter(x=>x.id!==s.id);ui.section=w.sections[0]?.id||'';touch(w);render();}},
'add-step':async()=>{const w=current(),s=section();if(w.sections.reduce((n,s)=>n+s.steps.length,0)>=240)throw new Error('最多240个子步骤');const name=await promptBox('子步骤名称');if(name){s.steps.push({id:C.uid(),name,duration:0});touch(w);render();}},
'step-up':el=>{const s=section(),i=s.steps.findIndex(t=>t.id===el.dataset.id);if(i>0){s.steps=C.move(s.steps,i,i-1);touch(current());render();}},
'step-down':el=>{const s=section(),i=s.steps.findIndex(t=>t.id===el.dataset.id);if(i<s.steps.length-1){s.steps=C.move(s.steps,i,i+1);touch(current());render();}},
'step-delete':async el=>{if(await confirmBox('删除子步骤','删除这个子步骤及关联到它的音乐？音乐文件会保留。')){C.removeStep(section(),el.dataset.id);touch(current());render();}},
'choose-music':()=>chooseMusic(),'link-music':el=>{section().music.push({id:C.uid(),assetId:el.dataset.id,stepId:'',usage:'',cue:'',previewUrl:''});touch(current());$('#modal').dataset.music='';closeModal();render();},unlink:async el=>{if(await confirmBox('解除音乐关联','从当前环节移除此音乐？音乐库中仍可继续使用。')){section().music=section().music.filter(m=>m.id!==el.dataset.id);touch(current());render();}},
'import-music':()=>$('#music-input').click(),play:el=>play(el.dataset.id),'stop-audio':()=>{const a=$('#player audio');a.pause();$('#player').hidden=true;},
'music-url':el=>editMusicUrl(el.dataset.id),
'music-rename':async el=>{const asset=state.assets.find(a=>a.id===el.dataset.id);const name=await promptBox('音乐名称',asset.name);if(name){asset.name=name;if($('#player audio').dataset.asset===asset.id)$('#player .player-name').textContent=name;touch();render();}},
'music-delete':async el=>{const asset=state.assets.find(a=>a.id===el.dataset.id);if(refs(asset.id).length)throw new Error('音乐仍被婚礼或回收站项目引用，请先解除关联');if(await confirmBox('删除音乐','删除本机音乐文件？这个操作无法撤销，建议先导出备份。')){state.assets=state.assets.filter(a=>a.id!==asset.id);touch();await flush();if($('#player audio').dataset.asset===asset.id)actions['stop-audio']();await db.removeFile(asset.id);if(urls.has(asset.id)){URL.revokeObjectURL(urls.get(asset.id));urls.delete(asset.id);}render();}},
'download-logo':async()=>{const asset=state.assets.find(a=>a.id===state.brand.logo);const file=await db.getFile(state.brand.logo);if(!file)throw new Error('原图未找到');download(file,asset?.name||'品牌Logo.png');},
'import-logo':()=>$('#logo-input').click(),'remove-logo':async()=>{if(await confirmBox('移除品牌Logo','导出将不再显示当前Logo，品牌名称和落款会保留。')){const id=state.brand.logo;state.brand.logo='';state.assets=state.assets.filter(a=>a.id!==id);brandUrl='';touch();await flush();await db.removeFile(id);render();}},
export:()=>openExport(),'project-export':el=>openExport(el.dataset.id),'preview-export':()=>previewExport(),'download-export':()=>downloadExport(),template:el=>{if(ui.exportBusy)return;ui.template=el.dataset.value;document.querySelectorAll('.template-option').forEach(b=>b.classList.toggle('active',b.dataset.value===ui.template));invalidatePreview();},
backup:()=>backupAll(),'draft-backup':()=>backupAll(),'import-backup':()=>$('#backup-input').click(),'protect-storage':async()=>{const yes=await db.protect();toast(yes?'已获得持久存储保护，仍建议定期备份':'浏览器未授予保护，请定期备份资料');},'close-modal':()=>closeModal(),
'reload-saved':async()=>{if(await confirmBox('重新载入已保存资料','请先导出当前草稿备份。继续将放弃本页未保存的修改，读取浏览器中已保存的资料。')){localStorage.removeItem('wedding-web-draft');location.reload();}}
};
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;if(el.closest('.flow-card')&&el!==e.target.closest('.flow-card'))e.stopPropagation();guard(async()=>{await actions[el.dataset.action]?.(el);});});
$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeModal();});
$('#modal').addEventListener('submit',e=>{e.preventDefault();if(modalSubmit)guard(async()=>{const button=e.submitter;if(button)button.disabled=true;try{await modalSubmit(e.target);}finally{if(button)button.disabled=false;}});});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.search){ui.query=el.value;render();return;}if(el.dataset.exportOption){ui.options[el.dataset.exportOption]=el.checked;invalidatePreview();return;}if(!el.dataset.field)return;const parts=el.dataset.field.split(':'),w=current(),s=section();let value=el.value;if(['duration'].includes(parts.at(-1)))value=Math.max(0,Math.min(1440,Math.floor(Number(value)||0)));if(parts.at(-1)==='previewUrl'){el.setCustomValidity('');if(value.trim()){try{WMusicSheet.previewUrl(value);}catch(error){el.setCustomValidity(error.message);}}}if(parts[0]==='s'){if(parts[1].startsWith('notes.'))s.notes[parts[1].slice(6)]=value;else s[parts[1]]=value;touch(w);refreshFlow();}else if(parts[0]==='step'){s.steps.find(t=>t.id===parts[1])[parts[2]]=value;touch(w);}else if(parts[0]==='link'){s.music.find(m=>m.id===parts[1])[parts[2]]=value;touch(w);}else if(parts[0]==='w'){if(parts[1]==='start'&&!/^([01]\d|2[0-3]):[0-5]\d$/.test(value))return;w[parts[1]]=value;touch(w);refreshFlow();}else if(parts[0]==='b'){if(parts[1]==='logoScale'){value=C.logoScale(Number(value));document.querySelectorAll('[data-field="b:logoScale"]').forEach(input=>{if(input!==el)input.value=value;});}state.brand[parts[1]]=value;touch();if($('#logo-size-info'))$('#logo-size-info').textContent=logoSizeText();if($('#brand-preview'))$('#brand-preview').innerHTML=brandPreview();}});
$('#music-input').addEventListener('change',e=>{const files=Array.from(e.target.files);e.target.value='';if(files.length)guard(()=>importMusic(files));});$('#logo-input').addEventListener('change',e=>{const file=e.target.files[0];e.target.value='';if(file)guard(()=>importLogo(file));});$('#backup-input').addEventListener('change',e=>{const file=e.target.files[0];e.target.value='';if(file)guard(()=>restoreBackup(file));});
$('#player audio').addEventListener('loadedmetadata',()=>{const audio=$('#player audio'),a=state.assets.find(a=>a.id===audio.dataset.asset);if(a&&Number.isFinite(audio.duration)&&audio.duration>0&&Math.round(audio.duration)!==a.duration){a.duration=Math.round(audio.duration);touch();}});$('#player audio').addEventListener('error',()=>toast('这段音频暂时无法播放，请检查文件或尝试MP3格式',true));
const isFileDrag=e=>Array.from(e.dataTransfer?.types||[]).includes('Files');
document.addEventListener('keydown',e=>{const zone=e.target.closest('[data-drop-music]');if(zone&&(e.key==='Enter'||e.key===' ')){e.preventDefault();$('#music-input').click();}});
document.addEventListener('dragenter',e=>{if(!isFileDrag(e))return;const zone=e.target.closest('[data-drop-music]');if(zone){e.preventDefault();zone.classList.add('drag-active');}});
document.addEventListener('dragleave',e=>{const zone=e.target.closest('[data-drop-music]');if(zone&&!zone.contains(e.relatedTarget))zone.classList.remove('drag-active');});
document.addEventListener('dragover',e=>{if(!isFileDrag(e))return;e.preventDefault();const zone=e.target.closest('[data-drop-music]');e.dataTransfer.dropEffect=zone?'copy':'none';});
document.addEventListener('drop',e=>{if(!isFileDrag(e))return;e.preventDefault();e.stopImmediatePropagation();document.querySelectorAll('.drag-active').forEach(el=>el.classList.remove('drag-active'));const zone=e.target.closest('[data-drop-music]');if(!zone){toast('请把音频拖到标有“拖拽音乐到这里”的导入框');return;}const files=Array.from(e.dataTransfer.files||[]);if(files.length)guard(()=>importMusic(files));});
document.addEventListener('dragstart',e=>{const card=e.target.closest('.flow-card');if(!card)return;dragIndex=Number(card.dataset.index);e.dataTransfer.setData('text/plain',String(dragIndex));e.dataTransfer.effectAllowed='move';card.classList.add('dragging');});document.addEventListener('dragover',e=>{const card=e.target.closest('.flow-card');if(!card||dragIndex<0)return;e.preventDefault();document.querySelectorAll('.drag-over').forEach(x=>x.classList.remove('drag-over'));card.classList.add('drag-over');});document.addEventListener('drop',e=>{const card=e.target.closest('.flow-card');if(!card||dragIndex<0)return;e.preventDefault();guard(async()=>{const w=current();w.sections=C.move(w.sections,dragIndex,Number(card.dataset.index));dragIndex=-1;touch(w);refreshFlow();});});document.addEventListener('dragend',()=>{dragIndex=-1;document.querySelectorAll('.dragging,.drag-over').forEach(x=>x.classList.remove('dragging','drag-over'));});
window.addEventListener('beforeunload',e=>{if(saved<sequence){stash();e.preventDefault();e.returnValue='';}});document.addEventListener('visibilitychange',()=>{if(document.hidden&&saved<sequence)flush().catch(()=>{});});
window.addEventListener('storage',e=>{if(e.key==='wedding-web-draft'&&e.newValue)toast('另一个页面正在编辑，请避免同时修改相同资料');});
async function boot(){state=await db.load();base=state.revision;let draft;try{draft=JSON.parse(localStorage.getItem('wedding-web-draft')||'null');}catch{}if(draft?.state?.weddings&&draft.base===base){state=draft.state;sequence=1;toast('已恢复上次未完成的本机草稿');flush().catch(e=>toast(e.message,true));}else if(draft?.state?.weddings){const a=JSON.stringify({...draft.state,revision:0}),b=JSON.stringify({...state,revision:0});if(a!==b){state=draft.state;conflicted=true;sequence=1;toast('检测到版本不同的草稿，请先在“备份与帮助”中导出资料',true);}else localStorage.removeItem('wedding-web-draft');}await loadBrand();render();}
boot().catch(e=>{$('#app').innerHTML=`<main style="max-width:650px;margin:80px auto;padding:25px"><h1>暂时无法打开本机资料</h1><p style="line-height:1.9;margin-top:20px">${esc(e.message)}。请使用正常浏览模式，并允许此网站使用浏览器存储。更换浏览器不会自动迁移原来的资料。</p><button class="btn primary" style="margin-top:20px" onclick="location.reload()">重新尝试</button></main>`;});
})();
